<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {errorMessage,type Page} from '../../api/http'
import {qcApi,qcScopeSummary,qcBasisLabel,qcStatuses,type QcSpecification} from '../../api/qcSpecifications'
import {useAuthStore} from '../../stores/auth'
import DictionarySelect from '../../components/DictionarySelect.vue'
import ProcessLookup from '../process/ProcessLookup.vue'
const route=useRoute(),router=useRouter(),auth=useAuthStore()
const keyword=ref(String(route.query.keyword??'')),basisType=ref<string|null>(route.query.basisType?String(route.query.basisType):null),materialId=ref<string|null>(route.query.materialId?String(route.query.materialId):null),productId=ref<string|null>(route.query.productId?String(route.query.productId):null),status=ref(String(route.query.status??'')),busy=ref(false),error=ref('')
const data=ref<Page<QcSpecification>>({items:[],total:0,page:0,size:20})
const columns=[{title:'标准编码',dataIndex:'specificationCode'},{title:'标准名称',dataIndex:'specificationName'},{title:'标准的依据',key:'basis'},{title:'适用范围',key:'scope'},{title:'状态',key:'status'},{title:'更新时间',dataIndex:'updatedAt'},{title:'操作',key:'actions'}]
async function load(page=0){busy.value=true;error.value='';try{const params={page,size:20,keyword:keyword.value,basisType:basisType.value||undefined,materialId:materialId.value||undefined,productId:productId.value||undefined,status:status.value||undefined};data.value=await qcApi.list(params);await router.replace({query:Object.fromEntries(Object.entries(params).filter(([,v])=>v!==undefined&&v!=='').map(([k,v])=>[k,String(v)]))})}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function reset(){keyword.value='';basisType.value=null;materialId.value=null;productId.value=null;status.value='';void load()}
onMounted(()=>load(Number(route.query.page??0)))
</script>
<template><main data-ui-template="T1" class="admin-page master-page t1-query-list"><header class="admin-page-header"><div><h1>QC质量标准</h1><p>检验标准基础信息库：直接维护标准的依据、适用范围与检验项目，不设审批和版本。</p></div><a-button v-if="auth.can('qms:specification:create')" type="primary" @click="router.push('/quality/specifications/create')">＋ 新增标准</a-button></header>
<a-card title="查询条件" class="query-card"><form class="query-form" @submit.prevent="load()"><label><span class="form-field-label">编码 / 名称</span><a-input v-model:value="keyword" allow-clear maxlength="200"/></label><label><span class="form-field-label">标准的依据</span><DictionarySelect v-model="basisType" dict-code="QC_STANDARD_BASIS" placeholder="全部依据"/></label><label><span class="form-field-label">适用物料</span><ProcessLookup v-model="materialId" resource="materials" label="筛选适用物料" allow-clear/></label><label><span class="form-field-label">适用产品</span><ProcessLookup v-model="productId" resource="products" label="筛选适用产品" allow-clear/></label><label><span class="form-field-label">状态</span><a-select v-model:value="status" allow-clear aria-label="状态"><a-select-option v-for="(label,state) in qcStatuses" :key="state" :value="state">{{label}}</a-select-option></a-select></label><a-space><a-button type="primary" html-type="submit">查询</a-button><a-button @click="reset">重置</a-button></a-space></form></a-card>
<a-alert v-if="error" type="error" :message="error" show-icon/><a-card title="标准列表" class="result-card"><a-table :columns="columns" :data-source="data.items" :loading="busy" :pagination="false" row-key="id" :scroll="{x:1100}"><template #bodyCell="{column,record}"><template v-if="column.key==='basis'"><span>{{qcBasisLabel(record.basisType)}}</span><small v-if="record.basisReference" class="qc-basis-ref">{{record.basisReference}}</small></template><span v-else-if="column.key==='scope'">{{qcScopeSummary(record.scopes)}}</span><a-tag v-else-if="column.key==='status'" :color="record.status==='ACTIVE'?'green':'default'">{{qcStatuses[record.status as keyof typeof qcStatuses]??record.status}}</a-tag><a-space v-else-if="column.key==='actions'"><a-button type="link" @click="router.push(`/quality/specifications/${record.id}`)">{{auth.can('qms:specification:edit')?'编辑':'查看'}}</a-button></a-space></template></a-table><div class="table-footer"><span>共 {{data.total}} 条</span><a-pagination :current="data.page+1" :page-size="data.size" :total="data.total" :show-size-changer="false" @change="(page:number)=>load(page-1)"/></div></a-card></main></template>
<style scoped>.query-form :deep(.process-lookup){display:block;min-width:0;flex:1}.query-form :deep(.ant-select){width:100%}.qc-basis-ref{display:block;color:#667085;font-size:12px;overflow-wrap:anywhere}</style>
